let elements = document.querySelectorAll('[class*="chai-"]');

arr.forEach((obj) => {
    let name = Object.keys(obj)[0].slice(1);    
    let property = Object.values(obj)[0].property;
    let value = Object.values(obj)[0].value;

    elements.forEach((el) => {
        if (el.classList.contains(name)) {
            el.style[property] = value;
        }
    });
});








